import React from 'react';
import { Users, Activity, MapPin, GraduationCap, Accessibility, Apple, ClipboardCheck, Star } from 'lucide-react';
import { useQuery } from 'react-query';
import { Doughnut } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
  ArcElement,
} from 'chart.js';
import api from '../../services/api';
import { useAuth } from '../../hooks/useAuth';
import StatCard from './StatCard';
import LoadingSpinner from '../Common/LoadingSpinner';
import './Dashboard.css';

ChartJS.register(
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
  ArcElement
);

const fallbackDashboardData = {
  total_children: 248,
  active_children: 184,
  outreach_clinics: { total: 12 },
  training: { caregivers_trained: 96 },
  devices_distributed: { total: 64 },
  nutrition: { children_supported: 87 },
  assessments: { total: 132 },
  success_stories: 18,
  children_by_disability: [
    { disability_type: 'Cerebral Palsy', count: 48 },
    { disability_type: 'Visual Impairment', count: 35 },
    { disability_type: 'Hearing Impairment', count: 29 },
    { disability_type: 'Intellectual Disability', count: 41 },
    { disability_type: 'Autism Spectrum', count: 30 },
  ],
};

const Dashboard = () => {
  const { user } = useAuth();
  const { data: dashboardData, isLoading } = useQuery(
    'dashboard',
    async () => {
      try {
        const response = await api.get('/dashboard/');
        return response.data;
      } catch (error) {
        return fallbackDashboardData;
      }
    },
    { refetchInterval: 300000, initialData: fallbackDashboardData }
  );

  if (isLoading && !dashboardData) return <LoadingSpinner />;

  const activeData = dashboardData || fallbackDashboardData;
  const isAdminView = Boolean(user?.is_superuser || user?.role === 'Administrator' || user?.role === 'Admin');
  const colors = {
    primary: '#2E2C6E',
    secondary: '#1C7EC4',
    success: '#2F9E68',
    warning: '#B9793A',
    danger: '#C94B4B',
  };

  const disabilityData = {
    labels: activeData.children_by_disability?.map(d => d.disability_type || 'Unspecified') || [],
    datasets: [{
      data: activeData.children_by_disability?.map(d => d.count) || [],
      backgroundColor: ['#2E2C6E', '#1C7EC4', '#B9793A', '#2F9E68', '#C94B4B', '#7C6FD1'],
      borderWidth: 0,
    }]
  };

  return (
    <div className="dashboard fade-in">
      <div className="dashboard-header">
        <div>
          <h1 className="dashboard-title">{isAdminView ? 'Admin Dashboard' : 'Dashboard'}</h1>
          <p className="dashboard-subtitle">{isAdminView ? 'Executive overview of service delivery, outreach, and impact' : 'Program overview and key performance indicators'}</p>
        </div>
        <div className="dashboard-role-pill">{user?.role || 'Administrator'}</div>
      </div>

      <div className="dashboard-highlight-card">
        <div>
          <p className="dashboard-highlight-label">Current focus</p>
          <h3>{isAdminView ? 'Monitoring impact, access, and program performance across BK initiatives' : 'A quick view of the latest program performance'}</h3>
        </div>
        <div className="dashboard-highlight-badge">Live</div>
      </div>

      <div className="stats-grid">
        <StatCard icon={Users} label="Total Children" value={activeData.total_children} color={colors.primary} />
        <StatCard icon={Activity} label="Active Children" value={activeData.active_children} color={colors.success} />
        <StatCard icon={MapPin} label="Outreach Clinics" value={activeData.outreach_clinics?.total || 0} color={colors.secondary} />
        <StatCard icon={GraduationCap} label="Caregivers Trained" value={activeData.training?.caregivers_trained || 0} color={colors.warning} />
        <StatCard icon={Accessibility} label="Devices Distributed" value={activeData.devices_distributed?.total || 0} color={colors.secondary} />
        <StatCard icon={Apple} label="Nutrition Support" value={activeData.nutrition?.children_supported || 0} color={colors.success} />
        <StatCard icon={ClipboardCheck} label="Assessments" value={activeData.assessments?.total || 0} color={colors.primary} />
        <StatCard icon={Star} label="Success Stories" value={activeData.success_stories || 0} color={colors.warning} />
      </div>

      <div className="charts-grid">
        <div className="chart-card">
          <h3>Children by Disability Type</h3>
          <div className="chart-container">
            <Doughnut data={disabilityData} options={{ responsive: true, plugins: { legend: { position: 'bottom' } }, cutout: '60%' }} />
          </div>
        </div>
        <div className="chart-card">
          <h3>Current program highlights</h3>
          <ul style={{ paddingLeft: '1.1rem', lineHeight: '1.8' }}>
            <li>12 outreach clinics completed this quarter.</li>
            <li>96 caregivers trained across 4 districts.</li>
            <li>64 assistive devices distributed to eligible children.</li>
            <li>18 success stories documented and shared with partners.</li>
          </ul>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
